BEGIN TRANSACTION;
CREATE TABLE "crm_opps" (
"event_id" TEXT,
  "user_id" INTEGER,
  "account_id" INTEGER,
  "event_type" TEXT,
  "pipeline_value" REAL,
  "timestamp" TIMESTAMP,
  "utm_campaign" TEXT
);
CREATE TABLE "crm_users" (
"user_id" INTEGER,
  "account_id" INTEGER,
  "company_name" TEXT,
  "email" TEXT,
  "first_name" TEXT,
  "last_name" TEXT,
  "seniority" TEXT
);
CREATE TABLE "ga4_events" (
"session_id" TEXT,
  "cookie_id" TEXT,
  "utm_source" TEXT,
  "utm_campaign" TEXT,
  "page_viewed" TEXT,
  "bounce_flag" INTEGER,
  "timestamp" TIMESTAMP,
  "user_id" REAL
);
CREATE TABLE "linkedin_events" (
"event_id" TEXT,
  "campaign_id" TEXT,
  "ad_id" TEXT,
  "cookie_id" TEXT,
  "utm_source" TEXT,
  "spend_consumed" REAL,
  "timestamp" TIMESTAMP,
  "user_id" REAL
);
CREATE TABLE "mailchimp_events" (
"event_id" TEXT,
  "email" TEXT,
  "campaign_id" TEXT,
  "action" TEXT,
  "url_clicked" TEXT,
  "timestamp" TIMESTAMP,
  "user_id" INTEGER
);
CREATE TABLE "master_summary" (
"user_id" INTEGER,
  "account_id" INTEGER,
  "company_name" TEXT,
  "email" TEXT,
  "first_name" TEXT,
  "last_name" TEXT,
  "seniority" TEXT,
  "pipeline_value" REAL,
  "mc_events" INTEGER,
  "ga4_events" INTEGER,
  "spend_consumed" REAL
);
COMMIT;
